     1→import { beforeEach, describe, expect, it } from "vitest";
     2→import type { BreadcrumbStackItem } from "@/navigation/breadcrumb-builder";
     3→import {
     4→  TAB_STORE_STORAGE_KEY,
     5→  getTabCurrentLeaf,
     6→  getTabCurrentState,
     7→  getTabUrl,
     8→  getTabViewModel,
     9→  mergePersistedTabState,
    10→  useTabStore,
    11→  type ClosedTabSnapshot,
    12→  type PageTab,
    13→  type TabNavigationState,
    14→} from "./tab-store";
    15→
    16→const FORBIDDEN_PAGE_TAB_FIELDS = [
    17→  "label",
    18→  "icon",
    19→  "descriptorId",
    20→  "meta",
    21→  "target",
    22→  "sourceNodeId",
    23→  "parentNodeId",
    24→  "history",
    25→] as const;
    26→
    27→function leaf(
    28→  id: string,
    29→  label: string,
    30→  href: string,
    31→  meta?: BreadcrumbStackItem["meta"]
    32→): BreadcrumbStackItem {
    33→  return {
    34→    id,
    35→    label,
    36→    href,
    37→    meta,
    38→  };
    39→}
    40→
    41→function state(url: string, stack: BreadcrumbStackItem[] = []): TabNavigationState {
    42→  return { url, breadcrumbStack: stack };
    43→}
    44→
    45→function documentsState(): TabNavigationState {
    46→  return state("/documents", [leaf("documents", "Documents", "/documents")]);
    47→}
    48→
    49→function settingsState(section: "general" | "about"): TabNavigationState {
    50→  const url = `/settings/${section}`;
    51→  return state(url, [leaf("settings", section === "general" ? "General" : "About", url)]);
    52→}
    53→
    54→function workspaceAgentsState(workspaceId = "workspace-a"): TabNavigationState {
    55→  const url = `/workspace/${workspaceId}/agent`;
    56→  return state(url, [
    57→    leaf("workspace", "Workspace A", `/workspace/${workspaceId}`, { workspaceId }),
    58→    leaf("workspace-section:agent", "Agents", url, { workspaceId, section: "agent" }),
    59→  ]);
    60→}
    61→
    62→function agentDetailState(workspaceId = "workspace-a", agentId = "agent-a"): TabNavigationState {
    63→  const url = `/workspace/${workspaceId}/agent/${agentId}`;
    64→  return state(url, [
    65→    ...workspaceAgentsState(workspaceId).breadcrumbStack,
    66→    leaf("workspace-agent", "Personal Assistant", url, { workspaceId, agentId }),
    67→  ]);
    68→}
    69→
    70→function makeTab(partial: {
    71→  id: string;
    72→  pinned?: boolean;
    73→  historyIndex?: number;
    74→  navigationHistory?: TabNavigationState[];
    75→  viewMode?: PageTab["viewMode"];
    76→}): PageTab {
    77→  return {
    78→    id: partial.id,
    79→    pinned: partial.pinned ?? false,
    80→    historyIndex: partial.historyIndex ?? 0,
    81→    navigationHistory: partial.navigationHistory ?? [documentsState()],
    82→    viewMode: partial.viewMode,
    83→  };
    84→}
    85→
    86→function makeClosedSnapshot(tab: PageTab, originIndex: number): ClosedTabSnapshot {
    87→  return {
    88→    tab,
    89→    originIndex,
    90→    closedAt: Date.now(),
    91→  };
    92→}
    93→
    94→function expectNoRemovedPageTabFields(tab: PageTab) {
    95→  for (const field of FORBIDDEN_PAGE_TAB_FIELDS) {
    96→    expect(tab).not.toHaveProperty(field);
    97→  }
    98→}
    99→
   100→function mergePersisted(input: {
   101→  tabs?: unknown[];
   102→  activeTabId?: string | null;
   103→  recentlyClosedTabs?: unknown[];
   104→}) {
   105→  return mergePersistedTabState(
   106→    {
   107→      tabs: input.tabs as PageTab[] | undefined,
   108→      activeTabId: input.activeTabId ?? null,
   109→      recentlyClosedTabs: input.recentlyClosedTabs as ClosedTabSnapshot[] | undefined,
   110→    },
   111→    {
   112→      tabs: [],
   113→      activeTabId: null,
   114→      recentlyClosedTabs: [],
   115→    }
   116→  );
   117→}
   118→
   119→describe("tab-store URL-based navigation state", () => {
   120→  beforeEach(() => {
   121→    useTabStore.setState({
   122→      tabs: [],
   123→      activeTabId: null,
   124→      recentlyClosedTabs: [],
   125→    });
   126→  });
   127→
   128→  it("uses a new persisted storage key and ignores the old tab store key", () => {
   129→    expect(TAB_STORE_STORAGE_KEY).toBe("viben-tab-store-v2");
   130→    expect(TAB_STORE_STORAGE_KEY).not.toBe("viben-tab-store");
   131→  });
   132→
   133→  it("does not define a legacy persisted storage key", () => {
   134→    expect(TAB_STORE_STORAGE_KEY).not.toBe("viben-tab-store");
   135→  });
   136→
   137→  it("merges v2 persisted state and drops invalid new-structure tabs without reading legacy fields", () => {
   138→    const validTab = makeTab({
   139→      id: "tab-valid",
   140→      pinned: true,
   141→      historyIndex: 5,
   142→      navigationHistory: [workspaceAgentsState(), agentDetailState()],
   143→      viewMode: "skill",
   144→    });
   145→    const invalidLegacyTab = {
   146→      id: "tab-legacy",
   147→      pinned: false,
   148→      historyIndex: 0,
   149→      history: ["/workspace/workspace-a/agent"],
   150→      label: "Legacy",
   151→    };
   152→    const snapshotTab = makeTab({
   153→      id: "tab-closed",
   154→      navigationHistory: [settingsState("about")],
   155→      viewMode: "page",
   156→    });
   157→
   158→    const result = mergePersisted({
   159→      tabs: [validTab, invalidLegacyTab],
   160→      activeTabId: "missing-tab",
   161→      recentlyClosedTabs: [
   162→        makeClosedSnapshot(snapshotTab, 4),
   163→        { tab: invalidLegacyTab, originIndex: 1, closedAt: Date.now() },
   164→      ],
   165→    });
   166→
   167→    expect(result.tabs).toHaveLength(1);
   168→    expect(result.tabs[0]).toMatchObject({
   169→      id: "tab-valid",
   170→      pinned: true,
   171→      historyIndex: 1,
   172→      viewMode: "skill",
   173→    });
   174→    expect(result.tabs[0].navigationHistory).toEqual([
   175→      workspaceAgentsState(),
   176→      agentDetailState(),
   177→    ]);
   178→    expect(result.activeTabId).toBe("tab-valid");
   179→    expectNoRemovedPageTabFields(result.tabs[0]);
   180→
   181→    expect(result.recentlyClosedTabs).toHaveLength(1);
   182→    expect(result.recentlyClosedTabs[0].tab.id).toBe("tab-closed");
   183→    expect(result.recentlyClosedTabs[0].originIndex).toBe(4);
   184→    expectNoRemovedPageTabFields(result.recentlyClosedTabs[0].tab);
   185→  });
   186→
   187→  it("partializes only the new PageTab shape", () => {
   188→    const openedId = useTabStore.getState().openTab({
   189→      navigationState: agentDetailState(),
   190→      pinned: true,
   191→      viewMode: "page",
   192→    });
   193→
   194→    const storeState = useTabStore.getState();
   195→    const persisted = {
   196→      tabs: storeState.tabs,
   197→      activeTabId: storeState.activeTabId,
   198→      recentlyClosedTabs: storeState.recentlyClosedTabs,
   199→    };
   200→
   201→    expect(persisted.activeTabId).toBe(openedId);
   202→    expect(persisted.tabs).toHaveLength(1);
   203→    expect(Object.keys(persisted.tabs[0]).sort()).toEqual([
   204→      "historyIndex",
   205→      "id",
   206→      "navigationHistory",
   207→      "pinned",
   208→      "viewMode",
   209→    ]);
   210→    expectNoRemovedPageTabFields(persisted.tabs[0]);
   211→  });
   212→
   213→  it("PageTab fixtures only contain tab container fields and navigation history", () => {
   214→    const tab = makeTab({ id: "tab-a" });
   215→
   216→    expect(Object.keys(tab).sort()).toEqual([
   217→      "historyIndex",
   218→      "id",
   219→      "navigationHistory",
   220→      "pinned",
   221→      "viewMode",
   222→    ]);
   223→    expectNoRemovedPageTabFields(tab);
   224→  });
   225→
   226→  it("opens a tab from navigationState without persisting breadcrumb leaf fields on PageTab", () => {
   227→    const openedId = useTabStore.getState().openTab({
   228→      navigationState: workspaceAgentsState(),
   229→      pinned: false,
   230→    });
   231→
   232→    const opened = useTabStore.getState().tabs.find((tab) => tab.id === openedId);
   233→    expect(opened).toBeTruthy();
   234→    expect(opened?.navigationHistory).toEqual([workspaceAgentsState()]);
   235→    expect(opened?.historyIndex).toBe(0);
   236→    expect(opened).toBeDefined();
   237→    expectNoRemovedPageTabFields(opened!);
   238→  });
   239→
   240→  it("duplicates a tab with the same navigation history and no removed fields", () => {
   241→    const original = makeTab({
   242→      id: "tab-a",
   243→      pinned: true,
   244→      historyIndex: 1,
