   260→    expect(duplicated?.historyIndex).toBe(original.historyIndex);
   261→    expect(duplicated?.navigationHistory).toEqual(original.navigationHistory);
   262→    expect(duplicated?.viewMode).toBe("skill");
   263→    expect(duplicated?.pinned).toBe(false);
   264→    expect(useTabStore.getState().activeTabId).toBe(duplicatedId);
   265→    expect(useTabStore.getState().tabs.map((tab) => tab.id)).toEqual([
