   310→    ]);
   311→    expect(reopened).toBeDefined();
   312→    expectNoRemovedPageTabFields(reopened!);
   313→  });
   314→
   315→  it("reopenClosedTab returns null when there is no snapshot", () => {
   316→    expect(useTabStore.getState().reopenClosedTab()).toBeNull();
   317→    expect(useTabStore.getState().tabs).toEqual([]);
