   319→
   320→  it("jumpToHistory only changes historyIndex and leaves navigationHistory untouched", () => {
   321→    const tab = makeTab({
   322→      id: "tab-a",
   323→      historyIndex: 2,
   324→      navigationHistory: [documentsState(), settingsState("general"), settingsState("about")],
   325→    });
   326→
   327→    useTabStore.setState({
