   341→  it("replaceLocation replaces the current entry and truncates forward history", () => {
   342→    const tab = makeTab({
   343→      id: "tab-a",
   344→      historyIndex: 1,
   345→      navigationHistory: [documentsState(), agentDetailState(), settingsState("about")],
   346→    });
   347→
   348→    useTabStore.setState({
   349→      tabs: [tab],
