   385→  it("pushLocation truncates forward history before appending the next entry", () => {
   386→    const tab = makeTab({
   387→      id: "tab-a",
   388→      historyIndex: 0,
   389→      navigationHistory: [workspaceAgentsState(), agentDetailState()],
