   102→function buildStateFromUrl(url?: string): TabNavigationState {
   103→  const targetUrl = url ?? "/documents";
   104→  const stack = buildColdStartBreadcrumb(targetUrl);
   105→  return { url: targetUrl, breadcrumbStack: stack };
   106→}
   107→
   108→function isNavigationState(value: unknown): value is TabNavigationState {
   109→  if (!value || typeof value !== "object") return false;
   110→  const candidate = value as Partial<TabNavigationState>;
   111→  return typeof candidate.url === "string" && Array.isArray(candidate.breadcrumbStack);
   112→}
   113→
   114→function isPersistedPageTab(value: unknown): value is PageTab {
   115→  if (!value || typeof value !== "object") return false;
   116→  const candidate = value as Partial<PageTab>;
   117→  return typeof candidate.id === "string" && Array.isArray(candidate.navigationHistory);
   118→}
   119→
   120→function isPersistedSnapshot(value: unknown): value is ClosedTabSnapshot {
   121→  if (!value || typeof value !== "object") return false;
   122→  const candidate = value as Partial<ClosedTabSnapshot>;
   123→  return (
   124→    isPersistedPageTab(candidate.tab) &&
   125→    typeof candidate.originIndex === "number" &&
   126→    typeof candidate.closedAt === "number"
   127→  );
   128→}
   129→
   130→function normalizeTab(tab: PageTab): PageTab {
   131→  const navigationHistory = tab.navigationHistory.filter(isNavigationState);
   132→  const safeHistory = navigationHistory.length > 0 ? navigationHistory : [buildStateFromUrl("/workspace")];
   133→  const historyIndex = Math.min(
   134→    Math.max(tab.historyIndex ?? safeHistory.length - 1, 0),
   135→    safeHistory.length - 1
   136→  );
   137→
   138→  return {
   139→    id: tab.id,
   140→    pinned: Boolean(tab.pinned),
   141→    historyIndex,
   142→    navigationHistory: safeHistory,
   143→    viewMode: tab.viewMode,
   144→  };
   145→}
   146→
   147→function normalizeSnapshot(snapshot: ClosedTabSnapshot): ClosedTabSnapshot {
   148→  return {
   149→    tab: normalizeTab(snapshot.tab),
   150→    originIndex: snapshot.originIndex,
   151→    closedAt: snapshot.closedAt,
   152→  };
   153→}
