   155→export function mergePersistedTabState(
   156→  persisted: Partial<TabState> | undefined,
   157→  current: TabState
   158→): TabState {
   159→  const tabs = (persisted?.tabs ?? []).filter(isPersistedPageTab).map(normalizeTab);
   160→  const tabIds = new Set(tabs.map((tab) => tab.id));
   161→  const activeTabId =
   162→    persisted?.activeTabId && tabIds.has(persisted.activeTabId)
   163→      ? persisted.activeTabId
   164→      : tabs[0]?.id ?? null;
   165→
   166→  return {
   167→    ...current,
   168→    tabs,
   169→    activeTabId,
   170→    recentlyClosedTabs: (persisted?.recentlyClosedTabs ?? [])
   171→      .filter(isPersistedSnapshot)
   172→      .map(normalizeSnapshot),
   173→  };
   174→}
