   192→function pushClosedSnapshots(
   193→  stack: ClosedTabSnapshot[],
   194→  snapshots: ClosedTabSnapshot[]
   195→): ClosedTabSnapshot[] {
   196→  if (snapshots.length === 0) {
   197→    return stack;
   198→  }
   199→
   200→  return [...snapshots].reverse().concat(stack).slice(0, MAX_RECENTLY_CLOSED_TABS);
