   203→function restoreClosedTabIntoTabs(
   204→  tabs: PageTab[],
   205→  snapshot: ClosedTabSnapshot
   206→): { tabs: PageTab[]; restoredTab: PageTab } {
   207→  const restoredTab = cloneTabWithNewId(snapshot.tab);
